def mono(p, n=256):
    xs = [a for a, b in p]; ys = [b for a, b in p]; m = len(xs)
    d = [(ys[i+1]-ys[i]) / max(1e-6, xs[i+1]-xs[i]) for i in range(m-1)]
    ms = [0.0]*m; ms[0] = d[0]; ms[-1] = d[-1]
    for i in range(1, m-1): ms[i] = 0 if d[i-1]*d[i] <= 0 else (d[i-1]+d[i])/2
    for i in range(m-1):
        if d[i] == 0: ms[i] = ms[i+1] = 0; continue
        a = ms[i]/d[i]; b = ms[i+1]/d[i]; s = a*a+b*b
        if s > 9: t = 3/s**0.5; ms[i] = t*a*d[i]; ms[i+1] = t*b*d[i]
    out = []
    for k in range(n):
        x = k/(n-1); i = 0
        while i < m-2 and x > xs[i+1]: i += 1
        h = xs[i+1]-xs[i]; t = (x-xs[i])/h if h > 0 else 0
        y = (2*t**3-3*t**2+1)*ys[i] + (t**3-2*t**2+t)*h*ms[i] + (-2*t**3+3*t**2)*ys[i+1] + (t**3-t**2)*h*ms[i+1]
        out.append(max(0, min(255, round(y*255))))
    return out

def bb_rgb(T):
    t = T/100
    if t <= 66:
        r = 255; g = 99.4708025861*math.log(t)-161.1195681661; b = 0 if t <= 19 else 138.5177312231*math.log(t-10)-305.0447927307
    else:
        r = 329.698727446*(t-60)**-0.1332047592; g = 288.1221695283*(t-60)**-0.0755148492; b = 255
    c = [max(0, min(255, v))/255 for v in (r, g, b)]; m = max(c); return [v/m for v in c]

def blackbody(lo, hi, gam=1.0):
    R, G, B = [], [], []
    for k in range(256):
        t = k/255; T = 1e6/(1e6/lo + (1e6/hi-1e6/lo)*t); br = t**gam
        r, g, b = [round(255*v*br) for v in bb_rgb(T)]; R.append(r); G.append(g); B.append(b)
    return R, G, B

def from_points(p): return mono(p['r']), mono(p['g']), mono(p['b'])
def swap_rb(p): return {'r': p['b'], 'g': p['g'], 'b': p['r']}

BANK = [
    ("silver",    ([g for g in range(256)],)*3),          # plain greyscale
    ("forge",     blackbody(1000, 6500)),                  # black body, 1000 K -> 6500 K
    ("bruise",    from_points(USER1)),                     # muted red, blue surges in the midtones
    ("glacier",   from_points(USER2)),                     # blue-led, red capped at 75%
    ("fathom",    from_points(USER3)),                     # glacier with darker shadows
    ("orchid",    from_points(USER4)),                     # green pinned to zero: magenta ramp
    ("amber",     from_points(USER5)),                     # warm, blue only in the top quarter
    ("abyss",     from_points(USER6)),                     # near-black shadows, blue climbs first
    ("cobalt",    from_points(USER7)),                     # pure blue, then snaps to white at ~50%
    ("cinder",    from_points(swap_rb(USER7))),            # cobalt with red and blue swapped
]

row = lambda a: ','.join(str(v) for v in a)
out = ['// Generated by tools/gen_curves.py -- do not edit. Double-tap cycles through these in order.',
       '#pragma once', '#include <stdint.h>', f'constexpr int N_CURVES = {len(BANK)};',
       'static const char* const CURVE_NAMES[N_CURVES] = {' + ', '.join(f'"{n}"' for n, _ in BANK) + '};',
       'static const uint8_t CURVES[N_CURVES][3][256] = {']
for name, (R, G, B) in BANK:
    out.append(f'  {{ // {name}\n    {{{row(R)}}},\n    {{{row(G)}}},\n    {{{row(B)}}} }},')
out.append('};')
here = os.path.dirname(os.path.abspath(__file__))
open(os.path.join(here, '..', 'src', 'comet', 'curves.h'), 'w').write('\n'.join(out) + '\n')
print('wrote', len(BANK), 'curves')
